const C=id=>document.getElementById('c-'+id),cen=document.documentElement.lang==='en',CT=(vi,en)=>cen?en:vi,CF=(v,n=2)=>v==null?'—':Number(v).toLocaleString(cen?'en-US':'vi-VN',{maximumFractionDigits:n});const componentNames={walls:CT('Tường ngoài','External walls'),roof:CT('Mái','Roof'),glass:CT('Kính & nắng','Glazing & solar'),people:CT('Người','Occupants'),lights:CT('Chiếu sáng','Lighting'),equipment:CT('Thiết bị','Equipment'),air:CT('Gió tươi & lọt khí','Outdoor air & infiltration'),other:CT('Tải khác','Other gains')};const heatInputs=[...document.querySelectorAll('.heat-workspace input')],heatDefaults=Object.fromEntries(heatInputs.map(el=>[el.id,el.value]));
let lastCoolingResult=null;
function coolingUpdate(){let valid=heatInputs.every(el=>el.value.trim()!==''&&Number.isFinite(+el.value)&&+el.value>=+el.min&&+el.value<=+el.max),x=Object.fromEntries(heatInputs.map(el=>[el.id.slice(2),+el.value]));valid=valid&&Number.isInteger(x.people)&&Number.isInteger(x.units);let r;if(valid)try{r=heatLoad(x);}catch{valid=false;}C('error').hidden=valid;lastCoolingResult=valid?{x,r}:null;C('pdf').disabled=!valid;C('preview').disabled=!valid;if(!valid){C('error').textContent=CT('Nhập thông số hợp lệ trong giới hạn của từng ô. Số người và số máy phải là số nguyên.','Enter valid values within each field’s limits. Occupants and unit count must be integers.');['design','btu','total','shr','density','sensible','latent','air'].forEach(id=>C(id).textContent='—');['choice','breakdown','table'].forEach(id=>C(id).innerHTML='');return;}C('design').innerHTML=CF(r.design/1000)+' <small>kW</small>';C('btu').textContent=CF(r.design*3.412141633,0)+' BTU/h · '+CT('đã cộng dự phòng ','with ')+CF(x.margin)+'%'+CT('',' allowance');C('total').textContent=CF(r.total/1000)+' kW';C('shr').textContent=CF(r.shr,3);C('density').textContent=CF(r.total/x.area,0)+' W/m²';C('sensible').textContent=CF(r.sensible/1000);C('latent').textContent=CF(r.latent/1000);C('air').textContent=CF(r.airflow,1);
const chosen=r.chosen;C('choice').innerHTML=chosen?`<div class="heat-choice"><strong>${CF(x.units,0)} × ${CF(chosen.btu,0)} BTU/h</strong><p>${CT('Mỗi máy: ','Per unit: ')}${CF(chosen.btu/3412.141633)} kW · ${CT('Tổng công suất khả dụng: ','Total available capacity: ')}${CF(chosen.capacity/1000)} kW</p><p>${CT('Công suất lạnh hiện / ẩn khả dụng: ','Available sensible / latent: ')}${CF(chosen.s/1000)} / ${CF(chosen.l/1000)} kW</p><p>${CT('Tải nhiệt hiện / ẩn yêu cầu (đã dự phòng): ','Required sensible / latent (with allowance): ')}${CF(r.requiredS/1000)} / ${CF(r.requiredL/1000)} kW</p></div>`:`<p class="heat-alert">${r.total===0?CT('Không có tải lạnh dương với thông số hiện tại.','No positive cooling load under the current assumptions.'):CT('Chưa có bậc công suất đáp ứng cả tải nhiệt hiện và tải nhiệt ẩn. Kiểm tra tỷ số nhiệt hiện (SHR) của thiết bị, chia thêm máy hoặc xử lý ẩm riêng.','No reference size meets both sensible and latent loads. Review equipment SHR, increase unit count or provide separate dehumidification.')}</p>`;
C('table').innerHTML=r.parts.map(part=>`<tr><td>${componentNames[part.key]}</td><td>${CF(part.s/1000)}</td><td>${CF(part.l/1000)}</td><td>${CF((part.s+part.l)/1000)}</td></tr>`).join('')+`<tr class="heat-total"><td>${CT('Tải dùng để chọn máy (chưa dự phòng)','Sizing load (before allowance)')}</td><td>${CF(r.sensible/1000)}</td><td>${CF(r.latent/1000)}</td><td>${CF(r.total/1000)}</td></tr>`;
const max=Math.max(1,...r.parts.map(p=>Math.max(0,p.s+p.l)));C('breakdown').innerHTML=r.parts.map(part=>`<div><div><span>${componentNames[part.key]}</span><strong>${CF((part.s+part.l)/1000)} kW</strong></div><div class="heat-bar"><i style="width:${100*Math.max(0,part.s+part.l)/max}%"></i></div></div>`).join('');}
heatInputs.forEach(el=>el.addEventListener('input',coolingUpdate));C('reset').onclick=()=>{heatInputs.forEach(el=>el.value=heatDefaults[el.id]);coolingUpdate();};coolingUpdate();
const reportEscape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function buildCoolingReport(){coolingUpdate();if(!lastCoolingResult)return null;const {x,r}=lastCoolingResult;let report=document.getElementById('cooling-report');if(!report){report=document.createElement('article');report.id='cooling-report';document.body.appendChild(report);}const date=new Date().toLocaleString(cen?'en-GB':'vi-VN',{timeZone:'Asia/Ho_Chi_Minh'});const inputs=[...document.querySelectorAll('.heat-input-group')].map(group=>'<section class="report-section"><h3>'+reportEscape(group.querySelector('summary').textContent)+'</h3><table><thead><tr><th>'+CT('Thông số','Input')+'</th><th>'+CT('Giá trị','Value')+'</th></tr></thead><tbody>'+[...group.querySelectorAll('input')].map(input=>'<tr><td>'+reportEscape(document.querySelector('label[for="'+input.id+'"]').textContent)+'</td><td>'+reportEscape(CF(+input.value,4)+' '+input.nextElementSibling.textContent)+'</td></tr>').join('')+'</tbody></table></section>').join('');
report.innerHTML=`<header class="report-heading"><div><b>HVAC Studio</b><h1>${CT('Báo cáo tính tải lạnh & chọn AC','Cooling load & AC sizing report')}</h1></div><p>${reportEscape(date)} · UTC+7<br>hvacstudio.vn</p></header><p class="report-scope">${CT('Ước tính sơ bộ một phòng theo cân bằng nhiệt tĩnh. Các giả thiết và thông số đầu vào được ghi đầy đủ bên dưới.','Preliminary single-room steady-state estimate. Assumptions and all inputs are recorded below.')}</p><section class="report-section"><h2>${CT('Kết quả tính','Calculation results')}</h2><table><tbody><tr><td>${CT('Tải lạnh phòng trước dự phòng','Room load before allowance')}</td><td>${CF(r.total/1000)} kW</td></tr><tr><td>${CT('Tải nhiệt hiện / tải nhiệt ẩn','Sensible / latent load')}</td><td>${CF(r.sensible/1000)} / ${CF(r.latent/1000)} kW</td></tr><tr><td>${CT('Công suất mục tiêu sau dự phòng','Target capacity with allowance')}</td><td><strong>${CF(r.design/1000)} kW · ${CF(r.design*3.412141633,0)} BTU/h</strong></td></tr><tr><td>${CT('Gió ngoài trời tổng','Total outdoor airflow')}</td><td>${CF(r.airflow)} m³/h</td></tr><tr><td>${CT('Suất tải theo sàn','Floor load density')}</td><td>${CF(r.total/x.area)} W/m²</td></tr></tbody></table><h3>${CT('Gợi ý thiết bị','Equipment suggestion')}</h3>${C('choice').innerHTML}</section><section class="report-section"><h2>${CT('Chi tiết thành phần tải — chưa gồm dự phòng','Component loads — before allowance')}</h2><table><thead><tr><th>${CT('Thành phần','Component')}</th><th>${CT('Hiện','Sensible')} (kW)</th><th>${CT('Ẩn','Latent')} (kW)</th><th>${CT('Tổng','Total')} (kW)</th></tr></thead><tbody>${C('table').innerHTML}</tbody></table></section><h2 class="report-input-heading">${CT('Thông số đầu vào','Design inputs')}</h2>${inputs}${window.HVACHeatPresets?.report()||''}<section class="report-section report-method"><h2>${CT('Phương pháp và phạm vi','Method and scope')}</h2>${document.querySelector('.method>div').innerHTML}<p>${CT('Gợi ý công suất không thay thế bảng lựa chọn máy. Kiểm tra khả năng làm giảm nhiệt độ và khử ẩm tại điều kiện thiết kế thực tế. Công suất lạnh không phải công suất điện.','The capacity suggestion does not replace equipment selection data. Verify sensible cooling and dehumidification capacities at actual design conditions. Cooling capacity is not electrical input.')}</p></section>`;return report;}
C('pdf').onclick=()=>{if(!buildCoolingReport())return;const previousTitle=document.title;document.title=cen?'HVAC-Studio-Cooling-Load':'HVAC-Studio-Bao-cao-tai-lanh';const restore=()=>{document.title=previousTitle;};window.addEventListener('afterprint',restore,{once:true});window.HVACPrint.run('cooling');};

C('preview').onclick=()=>{const report=buildCoolingReport();if(!report)return;document.getElementById('report-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='report-dialog';dialog.setAttribute('aria-label',CT('Xem báo cáo tính toán','Calculation report preview'));dialog.innerHTML='<div class="report-dialog-actions"><button class="text-button" type="button" id="report-close">'+CT('Đóng báo cáo','Close report')+' ×</button></div>'+report.innerHTML;document.body.append(dialog);dialog.querySelector('#report-close').onclick=()=>dialog.close();dialog.showModal();};
